\label{E_ratio_r}
\end{align}

To prove (i), we substitute $WC_{N,n,r} = \widetilde{WC}_{N,n,r} \cdot \mathcal{E}_{N,n,r}^C$ into the original relation $\gamma=0$, $\beta=1$ of \eqref{pizerorecursionone} and divide both sides by $\mathcal{E}_{N,n,r-1}^C(\mathbf{u}, \mathbf{w})$:
\begin{align*}
&\widetilde{WC}_{N,n,r-1}(\mathbf{u}|\mathbf{w}|\mathbf{I}^{(0)}) \nonumber \\
&= \frac{1}{1-w_1^2} \Bigg( (1-q)^{-1} \prod_{j=1}^n (1-q w_1^{-1} u_j^{-1})^{-1} \prod_{k=2}^{N} (1-q w_1 w_k)^{-1} \frac{\mathcal{E}_{N,n+1,r}^C(\mathbf{u}', \mathbf{w}')}{\mathcal{E}_{N,n,r-1}^C(\mathbf{u}, \mathbf{w})} 
\nonumber \\
&\times \widetilde{WC}_{N,n+1,r}(\mathbf{u}'|\mathbf{w}'|\mathbf{I})  -  w_1^2 \frac{\mathcal{E}_{N,n,r}^C(\mathbf{u}, \mathbf{w})}{\mathcal{E}_{N,n,r-1}^C(\mathbf{u}, \mathbf{w})} \widetilde{WC}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}) \Bigg).
\end{align*}
Decomposing the ratio of the normalization factors 
in the first term as \\
$\frac{\mathcal{E}^C_{N,n+1,r}(\mathbf{u}', \mathbf{w}')}{\mathcal{E}^C_{N,n,r-1}(\mathbf{u}, \mathbf{w})} = \frac{\mathcal{E}_{N,n+1,r}^C(\mathbf{u}', \mathbf{w}')}{\mathcal{E}^C_{N,n,r}(\mathbf{u}, \mathbf{w})} \cdot \frac{\mathcal{E}^C_{N,n,r}(\mathbf{u}, \mathbf{w})}{\mathcal{E}^C_{N,n,r-1}(\mathbf{u}, \mathbf{w})}$ and applying equations \eqref{E_ratio_shift} and \eqref{E_ratio_r}, equation \eqref{pizerorecursionone_tilde} is derived.

To prove (ii), we substitute $WC_{N,n,r} = \widetilde{WC}_{N,n,r} \cdot \mathcal{E}_{N,n,r}^C$ into the original relation $\gamma=0$, $\beta=1$ of
\eqref{pizerorecursiontwo} and divide both sides by $\mathcal{E}_{N,n+1,r}^C(\mathbf{u}', \mathbf{w}')$. This yields the following:
\begin{align*}
&\widetilde{WC}_{N,n+1,r}(\mathbf{u}'|\mathbf{w}'|\mathbf{I}) \nonumber \\
=& (1-q)  \prod_{j=1}^n (1-q w_1^{-1} u_j^{-1}) \prod_{k=2}^{N} (1-q w_1 w_k) \cdot \frac{\mathcal{E}^C_{N,n,r}(\mathbf{u}, \mathbf{w})}{\mathcal{E}_{N,n+1,r}^C(\mathbf{u}', \mathbf{w}')} \widetilde{WC}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}).
\end{align*}
Substituting the inverse of the ratio \eqref{E_ratio_shift} into this equation derives equation \eqref{pizerorecursiontwo_tilde}.

Assume $r\le n-2$. We have
\begin{align}
 \widetilde{WC}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I})\Big|_{u_i u_j = 1}& = \frac{(1-q)^2}{(1-qu_i^2)(1-qu_j^2)} \widetilde{WC}_{N,n-2,r}(\mathbf{u} \setminus \{u_i, u_j\}|\mathbf{w}|\mathbf{I}). \label{normalizedsusytwo} 
\end{align}

Direct substitution in \eqref{typeCnormalizationfactor} gives
\begin{align}
    &\frac{\mathcal{E}_{N,n,r}^C(\mathbf{u},\mathbf{w})|_{u_i u_j = 1}}{\mathcal{E}_{N,n-2,r}^C(\mathbf{u} \setminus \{u_i, u_j\}, \mathbf{w})} 
    = \frac{1}{1-q}(1-qu_i^2)(1-qu_j^2) 
   \nonumber \\ 
&\times    \prod_{k=1}^N (1-qu_iw_k)(1-qu_jw_k)  \prod_{\substack{k=1 \\ k \neq i,j}}^n (1-qu_k^{-1}u_i)(1-qu_k^{-1}u_j). \notag
\end{align}
Combining with $\gamma=0$, $\beta=1$ of
\eqref{reductionrelation},
we obtain \eqref{normalizedsusytwo}.

Assume $r\le n-1$. We have
\begin{align}
\widetilde{WC}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I})\Big|_{u_n = 1}& =\widetilde{WC}_{N,n-1,r}(\mathbf{u} \setminus \{ u_n \}|\mathbf{w}|\mathbf{I}).
\label{stabilityWC}
\end{align}

\label{prop:B_si}
Let $i \in \{1, \dotsm, N-1\}$. For the normalized weight function $\widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I})$, the following relations hold.

(i) If $i+1 = i_k \in \mathbf{I}$ and $i \notin \mathbf{I}$, we have
\begin{align}
&\widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}^{(i)}) \nonumber \\
=& \frac{1}{w_i-w_{i+1}} \Big( (w_i-q w_{i+1}) \widetilde{WB}_{N,n,r}(\mathbf{u}|s_i \mathbf{w}|\mathbf{I}) - (1-q)w_{i+1} \widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}) \Big), \\
&\widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}) \nonumber \\
=& \frac{1}{q(w_i-w_{i+1})} \Big( (w_i-q w_{i+1}) \widetilde{WB}_{N,n,r}(\mathbf{u}|s_i \mathbf{w}|\mathbf{I}^{(i)}) - (1-q)w_{i} \widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}^{(i)}) \Big),
\end{align}
here $\mathbf{I}^{(i)} = \{ i_1, \dotsm, i_{k-1}, i, i_{k+1}, \dotsm, i_r \}$.

(ii) If $i,i+1 \in \mathbf{I}$ or $i,i+1 \not\in \mathbf{I}$, we have
\begin{align}
\widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}) = \widetilde{WB}_{N,n,r}(\mathbf{u}|s_i \mathbf{w}|\mathbf{I}).
\end{align}

\label{prop:B_shift}
The normalized weight function $\widetilde{WB}_{N,n,r}$ satisfies the following boundary recursive relations.

(i) If $1 \in \mathbf{I}$, we have
\begin{align}
\widetilde{WB}_{N,n,r-1}(\mathbf{u}|\mathbf{w}|\mathbf{I}^{(0)}) =& \frac{1}{1-w_1} \Bigg( (1 - q w_1) \widetilde{WB}_{N,n+1,r}(\mathbf{u}, w_1^{-1}|w_1^{-1}, w_2, \dotsm, w_N|\mathbf{I}) \nonumber \\
&- (1-q) w_1 \widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}) \Bigg),
\end{align}
here $\mathbf{I}^{(0)}=\{ i_2,\dotsm,i_r \}$.

(ii) If $1 \not\in \mathbf{I}$, we have
\begin{align}
\widetilde{WB}_{N,n+1,r}(\mathbf{u}, w_1^{-1}|w_1^{-1}, w_2, \dotsm, w_N|\mathbf{I}) = \frac{1-q}{1-qw_1} \widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I}).
\end{align}

Assume $r\le n-2$. We have
\begin{align}
 \widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I})\Big|_{u_i u_j = 1}& = \frac{(1-q)^2}{(1-qu_i)(1-qu_j)} \widetilde{WB}_{N,n-2,r}(\mathbf{u} \setminus \{u_i, u_j\}|\mathbf{w}|\mathbf{I}). \label{normalizedsusythree}
\end{align}

Assume $r\le n-1$. We have
\begin{align}
\widetilde{WB}_{N,n,r}(\mathbf{u}|\mathbf{w}|\mathbf{I})\Big|_{u_n = 1}& =\widetilde{WB}_{N,n-1,r}(\mathbf{u} \setminus \{ u_n \}|\mathbf{w}|\mathbf{I}).
\label{stabilityWB}
\end{align}

If $|\mathbf{M}|<|\mathbf{I}|=r$, then
\begin{equation}
\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})=0.
\label{eq:typeC-lower-cardinality-vanishing}
\end{equation}

For every $s=|\mathbf{M}|$ with $r=|\mathbf{I}|\le s\le n$,
\begin{align}
\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
&=(1-q)^{s-r}
\prod_{\substack{j\le k\\j,k\in\mathbf{M}^{\mathrm c}}}
(1-qw_jw_k)
\sum_{\substack{\mathbf{K}\subset\mathbf{M}\\|\mathbf{K}|=r}}
\frac{
W_{N,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
}{
\displaystyle
\prod_{a,b=1}^{r}(1-qw_{k_a}^{-1}w_{k_b})
}
\notag\\
&\quad\times
\frac{
\displaystyle
\prod_{1\le a\le b\le r}
(1-w_{k_a}^{-1}w_{k_b}^{-1})
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-w_{k_a}^{-1}w_{l_b}^{-1})
}{
\displaystyle
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-w_{k_a}^{-1}w_{l_b})
}
\notag\\
&\quad\times
\prod_{1\le a<b\le s-r}
(1-qw_{l_a}^{-1}w_{l_b}^{-1})
\prod_{a=1}^{s-r}
\prod_{j\in\mathbf{M}^{\mathrm c}}
(1-qw_{l_a}^{-1}w_j).
\label{eq:typeC-cross-sector-branching}
\end{align}
For $r=0$, set $W_{N,0}=1$, and interpret every empty product as $1$.

By \eqref{eq:typeC-stability-s-ge-r},
$
\widetilde{WC}_{N,n,r}
(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
=
\widetilde{WC}_{N,s,r}
(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I}).
$
Therefore it is enough to decompose
$WC_{N,s,r}(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I})$.
Fix
$
\mathbf{K}=\{k_1<\cdots<k_r\}\subset\mathbf{M}$
and $
\mathbf{L}=\mathbf{M}\setminus\mathbf{K}
=\{l_1<\cdots<l_{s-r}\}.
$
By the definition \eqref{WCfunction},
$WC_{N,s,r}$ is obtained from the explicit formula \eqref{Motherfunction}
for $F_{N,s,r}$ by setting $\gamma=0$ and $\beta=1$.
We apply this specialized form of \eqref{Motherfunction} and collect the
permutations for which the variables in the first $r$ positions are precisely
$w_{k_1},\ldots,w_{k_r}$ and those in the remaining $s-r$ positions are
$w_{l_1},\ldots,w_{l_{s-r}}$.  The factors coupling these two sets are
invariant under permutations within either set.  Consequently, before any
further simplification, the specialized form of \eqref{Motherfunction} can be
written as the following sum over subsets:
\begin{align}
&WC_{N,s,r}(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I})
\notag\\
&=\frac{1}{(s-r)!}
\sum_{\substack{\mathbf{K}\subset\mathbf{M}\\|\mathbf{K}|=r}}
\prod_{a=1}^{r}w_{k_a}^{-(N+s)}
\prod_{b=1}^{s-r}w_{l_b}^{-(N+s)}
\notag\\
&\quad\times
\sum_{\sigma\in S_r}\sigma\Bigg[
\prod_{j=1}^{r}
\left\{
(1-q)(u_j^2-1)
\prod_{c=i_j+1}^{N}(u_j-qw_c)
\prod_{c=1}^{i_j-1}(u_j-w_c)
\right\}
\notag\\
&\hspace{40mm}\times
\prod_{1\le j<k\le r}
\frac{qu_j-u_k}{u_j-u_k}(u_ju_k-1)
\Bigg]_{(u_1,\ldots,u_r)=(w_{k_1},\ldots,w_{k_r})}
\notag\\
&\quad\times
\sum_{\rho\in S_{s-r}}\rho\Bigg[
\prod_{b=1}^{s-r}
\left\{
 u_{r+b}\prod_{c=1}^{N}(u_{r+b}-qw_c)
\right\}
\notag\\
&\quad\times
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
\frac{qu_{r+b}-w_{k_a}}{u_{r+b}-w_{k_a}}
(w_{k_a}u_{r+b}-1)
\prod_{1\le a<b\le s-r}(u_{r+a}u_{r+b}-q)
\Bigg]_{\substack{
(u_{r+1},\ldots,u_s)\\
=(w_{l_1},\ldots,w_{l_{s-r}})}}.
\label{eq:typeC-subset-sum-before-grouping}
\end{align}
We first evaluate the sum over $\rho$.  The action of $\rho$ permutes only
$u_{r+1},\ldots,u_s$.  Since each of the three products below is symmetric in
these variables, all $(s-r)!$ terms are equal.  Therefore
\begin{align}
&\frac{1}{(s-r)!}
\sum_{\rho\in S_{s-r}}\rho\Bigg[
\prod_{b=1}^{s-r}
\left\{
 u_{r+b}\prod_{c=1}^{N}(u_{r+b}-qw_c)
\right\}
\notag\\
&\times
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
\frac{qu_{r+b}-w_{k_a}}{u_{r+b}-w_{k_a}}
(w_{k_a}u_{r+b}-1)
\prod_{1\le a<b\le s-r}(u_{r+a}u_{r+b}-q)
\Bigg]_{\substack{
(u_{r+1},\ldots,u_s)\\
=(w_{l_1},\ldots,w_{l_{s-r}})}}
\notag\\
&=
\prod_{b=1}^{s-r}
\left\{
 w_{l_b}\prod_{c=1}^{N}(w_{l_b}-qw_c)
\right\}
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
\frac{qw_{l_b}-w_{k_a}}{w_{l_b}-w_{k_a}}
(w_{k_a}w_{l_b}-1)
\prod_{1\le a<b\le s-r}(w_{l_a}w_{l_b}-q).
 \notag
\end{align}
Thus the subset decomposition
\eqref{eq:typeC-subset-sum-before-grouping} becomes the following completely
explicit formula:
\begin{align}
&WC_{N,s,r}(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I})
=
\sum_{\substack{\mathbf{K}\subset\mathbf{M}\\|\mathbf{K}|=r}}
\prod_{a=1}^{r}w_{k_a}^{-(N+s)}
\prod_{b=1}^{s-r}w_{l_b}^{-(N+s)}
\notag\\
&\quad\times
\sum_{\sigma\in S_r}\sigma\Bigg[
\prod_{j=1}^{r}
\left\{
(1-q)(u_j^2-1)
\prod_{c=i_j+1}^{N}(u_j-qw_c)
\prod_{c=1}^{i_j-1}(u_j-w_c)
\right\}
\notag\\
&\quad\times
\prod_{1\le j<k\le r}
\frac{qu_j-u_k}{u_j-u_k}(u_ju_k-1)
\Bigg]_{(u_1,\ldots,u_r)=(w_{k_1},\ldots,w_{k_r})}
\prod_{b=1}^{s-r}
\left\{
w_{l_b}\prod_{c=1}^{N}(w_{l_b}-qw_c)
\right\}
\notag\\
&\quad\times
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
\frac{qw_{l_b}-w_{k_a}}{w_{l_b}-w_{k_a}}
(w_{k_a}w_{l_b}-1)
\prod_{1\le a<b\le s-r}(w_{l_a}w_{l_b}-q).
\label{eq:typeC-subset-sum-after-rho}
\end{align}
We next identify the $\sigma$-sum in each summand of
\eqref{eq:typeC-subset-sum-after-rho}.  Applying \eqref{Motherfunction}
with $n=r$, $\gamma=0$, and $\beta=1$, and then using the definition
\eqref{WCfunction},
\begin{align}
&\prod_{a=1}^{r}w_{k_a}^{-(N+s)}
\sum_{\sigma\in S_r}\sigma\Bigg[
\prod_{j=1}^{r}
\left\{
(1-q)(u_j^2-1)
\prod_{c=i_j+1}^{N}(u_j-qw_c)
\prod_{c=1}^{i_j-1}(u_j-w_c)
\right\}
\notag\\
&\hspace{34mm}\times
\prod_{1\le j<k\le r}
\frac{qu_j-u_k}{u_j-u_k}(u_ju_k-1)
\Bigg]_{(u_1,\ldots,u_r)=(w_{k_1},\ldots,w_{k_r})}
\notag\\
&\qquad=
WC_{N,r,r}
(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
\prod_{a=1}^{r}w_{k_a}^{-(s-r)}.
\label{eq:typeC-first-r-contribution}
\end{align}
Indeed, the monomial prefactor in $WC_{N,r,r}$ is
$\prod_{a=1}^{r}w_{k_a}^{-(N+r)}$, whereas the monomial prefactor inherited
from $WC_{N,s,r}$ is $\prod_{a=1}^{r}w_{k_a}^{-(N+s)}$.
Substituting~\eqref{eq:typeC-first-r-contribution} into
\eqref{eq:typeC-subset-sum-after-rho}, we obtain
\begin{align}
&WC_{N,s,r}(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I})
\notag\\
&=
\sum_{\substack{\mathbf{K}\subset\mathbf{M}\\|\mathbf{K}|=r}}
WC_{N,r,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
\prod_{a=1}^{r}w_{k_a}^{-(s-r)}
\prod_{b=1}^{s-r}w_{l_b}^{-(N+s)}
\notag\\
&\quad\times
\prod_{b=1}^{s-r}
\left\{
w_{l_b}\prod_{c=1}^{N}(w_{l_b}-qw_c)
\right\}
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
\frac{qw_{l_b}-w_{k_a}}{w_{l_b}-w_{k_a}}
(w_{k_a}w_{l_b}-1)
\prod_{1\le a<b\le s-r}(w_{l_a}w_{l_b}-q).
\label{eq:typeC-sum-through-WCrr}
\end{align}

We use
\begin{align}
&w_{l_b}^{-(N+s)}w_{l_b}
\prod_{c=1}^{N}(w_{l_b}-qw_c)
=
w_{l_b}^{1-s}
\prod_{k=1}^{N}(1-qw_{l_b}^{-1}w_k),
 \notag\\
&\frac{qw_{l_b}-w_{k_a}}{w_{l_b}-w_{k_a}}
(w_{k_a}w_{l_b}-1)
=
w_{k_a}w_{l_b}
\frac{
(1-qw_{k_a}^{-1}w_{l_b})
(1-w_{k_a}^{-1}w_{l_b}^{-1})
}{
1-w_{k_a}^{-1}w_{l_b}
},
 \notag\\
&w_{l_a}w_{l_b}-q
=
w_{l_a}w_{l_b}
(1-qw_{l_a}^{-1}w_{l_b}^{-1}).
 \notag
\end{align}

Applying~\eqref{relationwithAnormalized} with $n=r$ and $\mathbf{M}=\mathbf{K}$, and then using the normalized definition \eqref{typeCnormalizeddefinition}, gives
\begin{align}
&WC_{N,r,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
\notag\\
&=
\mathcal E^C_{N,r,r}(w_{k_1},\ldots,w_{k_r},\mathbf{w})
\prod_{1\le a\le b\le r}
(1-w_{k_a}^{-1}w_{k_b}^{-1})
\prod_{\substack{j\le k\\j,k\in\mathbf{K}^{\mathrm c}}}
(1-qw_jw_k)
\frac{
W_{N,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
}{
\displaystyle
\prod_{a,b=1}^{r}(1-qw_{k_a}^{-1}w_{k_b})
}.
 \notag
\end{align}
Here $\mathbf{K}^{\mathrm c}=\{1,\dots,N\}\setminus\mathbf{K}$.

Moreover,
\begin{align}
\frac{
\mathcal E^C_{N,r,r}(w_{k_1},\ldots,w_{k_r},\mathbf{w})
}{
\mathcal E^C_{N,s,r}(w_{m_1},\ldots,w_{m_s},\mathbf{w})
}
&=(1-q)^{s-r}
\frac{
\displaystyle
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-qw_{k_a}w_{l_b})
\prod_{1\le a<b\le s-r}
(1-qw_{l_a}w_{l_b})
}{
\displaystyle
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-qw_{k_a}^{-1}w_{l_b})
\prod_{a=1}^{s-r}\prod_{b=1}^{r}
(1-qw_{l_a}^{-1}w_{k_b})
}
\notag\\
&\qquad\times
\frac{1}{
\displaystyle
\prod_{a,b=1}^{s-r}(1-qw_{l_a}^{-1}w_{l_b})
\prod_{a=1}^{s-r}\prod_{j=1}^{N}(1-qw_{l_a}w_j)
}.
 \notag
\end{align}

Substituting these identities into the summand of
\eqref{eq:typeC-sum-through-WCrr} indexed by $\mathbf{K}$, and then dividing
by the normalization factor
$
\mathcal E^C_{N,s,r}(w_{m_1},\ldots,w_{m_s},\mathbf{w}),
$
we obtain
\begin{align}
&(1-q)^{s-r}
\prod_{\substack{j\le k\\j,k\in\mathbf{M}^{\mathrm c}}}
(1-qw_jw_k)
\frac{
W_{N,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
}{
\displaystyle
\prod_{a,b=1}^{r}(1-qw_{k_a}^{-1}w_{k_b})
}
\notag\\
&\quad\times
\frac{
\displaystyle
\prod_{1\le a\le b\le r}
(1-w_{k_a}^{-1}w_{k_b}^{-1})
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-w_{k_a}^{-1}w_{l_b}^{-1})
}{
\displaystyle
\prod_{a=1}^{r}\prod_{b=1}^{s-r}
(1-w_{k_a}^{-1}w_{l_b})
}
\notag\\
&\quad\times
\prod_{1\le a<b\le s-r}
(1-qw_{l_a}^{-1}w_{l_b}^{-1})
\prod_{a=1}^{s-r}
\prod_{j\in\mathbf{M}^{\mathrm c}}
(1-qw_{l_a}^{-1}w_j).
\label{eq:typeC-one-branch-explicit}
\end{align}
Summing~\eqref{eq:typeC-one-branch-explicit} over all
$\mathbf{K}\subset\mathbf{M}$ with $|\mathbf{K}|=r$ proves the formula.

Let $s=|\mathbf{M}|$ and assume $r\le s\le n$. Then
\begin{equation*}
\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})\ne0
\end{equation*}
only if
\begin{equation}
i_j\le m_{s-r+j}
\qquad(j=1,\ldots,r).
\label{eq:typeC-shifted-dominance}
\end{equation}
This is equivalent to $\lambda(\mathbf{I})\subseteq\lambda(\mathbf{M})$.

For every $\mathbf{M}=\{m_1<\cdots<m_s\}\subset\{1,\dots,N\}$ with $s\le n$,
\begin{equation}
\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
\in
\mathbb{C}(q)[w_1^{\pm1},\ldots,w_N^{\pm1}].
\label{eq:typeC-laurent-polynomiality}
\end{equation}
Moreover, this Laurent polynomial is divisible by
\begin{equation}
\prod_{\substack{j\le k\\j,k\in\mathbf{M}^{\mathrm c}}}
(1-qw_jw_k).
\label{eq:typeC-complement-factor-general-s}
\end{equation}

Using the stability relation \eqref{eq:typeC-stability-s-ge-r}, the normalized definition \eqref{typeCnormalizeddefinition}, and then substituting $u_j=w_{m_j}$ into the normalization factor \eqref{typeCnormalizationfactor}, we obtain
\begin{align}
&\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
=(1-q)^{s-r}
\prod_{\substack{j\le k\\j,k\in\mathbf{M}^{\mathrm c}}}
(1-qw_jw_k)
\frac{
WC_{N,s,r}(w_{m_1},\ldots,w_{m_s}|\mathbf{w}|\mathbf{I})
}{
\displaystyle
\prod_{j,k=1}^{s}(1-qw_{m_j}^{-1}w_{m_k})
}.
 \notag
\end{align}
The degree intervals of the products appearing here are
\begin{align*}
(1-q)^{s-r}&:\ [0,0],\\
\prod_{j,k=1}^{s}(1-qw_{m_j}^{-1}w_{m_k})&:\ [0,0],\\
\prod_{\substack{j\le k\\j,k\in\{1,\dots,N\}\setminus \mathbf{M}}}(1-qw_jw_k)
&:\ \left[0,4\tbinom{N-s+1}{2} \right]
=\left[0,2(N-s)(N-s+1) \right].
\end{align*}
Thus the lower endpoint is unchanged, while the upper endpoint becomes
\[
s(N-s)-r+|\mathbf{I}\cap \mathbf{M}|+2(N-s)(N-s+1)
=(N-s)(2N-s+2)-r+|\mathbf{I}\cap \mathbf{M}|.
\]

Let $s=|\mathbf{M}|$ satisfy $r\le s\le n$. If $\mathbf{I}\not\subseteq \mathbf{M}$ as sets, then $|\mathbf{I}\cap \mathbf{M}|\le r-1$, and therefore
\begin{align}
&\varphi_{\mathbf{M}}\left(
\mathcal N\left(
\widetilde{WC}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
\right)
\right)
\subset[-s(s+1),(N-s)(2N-s+2)-1].
\label{eq:typeC-strict-smallness-sufficient-condition}
\end{align}

If $|\mathbf{M}|<|\mathbf{I}|=r$, then
\begin{equation}
\widetilde{WB}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})=0.
\label{eq:typeB-lower-cardinality-vanishing}
\end{equation}

For every $s=|\mathbf{M}|$ with $r=|\mathbf{I}|\le s\le n$,
\begin{align}
&\widetilde{WB}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
\notag\\
&=(1-q)^{s-r}
\prod_{j\in\mathbf{M}^{\mathrm c}}(1-qw_j)
\prod_{\substack{j<k\\j,k\in\mathbf{M}^{\mathrm c}}}(1-qw_jw_k)
\sum_{\substack{\mathbf{K}\subset\mathbf{M}\\|\mathbf{K}|=r}}
\frac{
W_{N,r}(w_{k_1},\ldots,w_{k_r}|\mathbf{w}|\mathbf{I})
}{
\displaystyle
\prod_{a,b=1}^{r}(1-qw_{k_a}^{-1}w_{k_b})
}
\notag\\
&\quad\times
\frac{
\displaystyle
\prod_{a=1}^{r}(1-w_{k_a}^{-1})
\prod_{1\le a<b\le r}(1-w_{k_a}^{-1}w_{k_b}^{-1})
\prod_{a=1}^{r}\prod_{b=1}^{s-r}(1-w_{k_a}^{-1}w_{l_b}^{-1})
}{
\displaystyle
\prod_{a=1}^{r}\prod_{b=1}^{s-r}(1-w_{k_a}^{-1}w_{l_b})
}
\notag\\
&\quad\times
\prod_{1\le a<b\le s-r}(1-qw_{l_a}^{-1}w_{l_b}^{-1})
\prod_{a=1}^{s-r}\prod_{j\in\mathbf{M}^{\mathrm c}}
(1-qw_{l_a}^{-1}w_j).
\label{eq:typeB-cross-sector-branching}
\end{align}
For $r=0$, set $W_{N,0}=1$, and interpret every empty product as $1$.
If $s=r$, only the term $\mathbf{K}=\mathbf{M}$ remains, and the formula agrees with
\eqref{relationwithAnormalizedtypeB}.

Let $s=|\mathbf{M}|$ and assume $r\le s\le n$. Then
\[
\widetilde{WB}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})\ne0
\]
only if
\begin{equation}
i_j\le m_{s-r+j}
\qquad(1\le j\le r).
\label{eq:typeB-generalized-support-componentwise}
\end{equation}
This condition is equivalent to $\lambda(\mathbf{I})\subseteq\lambda(\mathbf{M})$.

For every $s=|\mathbf{M}|$ with $r\le s\le n$, the Laurent polynomial
\[
\widetilde{WB}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
\]
is divisible by
\begin{equation}
\prod_{j\in\mathbf{M}^{\mathrm c}}(1-qw_j)
\prod_{\substack{j<k\\j,k\in\mathbf{M}^{\mathrm c}}}(1-qw_jw_k).
\label{eq:typeB-complement-factor}
\end{equation}

Let $s=|\mathbf{M}|$ satisfy $r\le s\le n$. If $\mathbf{I}\not\subseteq\mathbf{M}$ as sets, then $|\mathbf{I}\cap\mathbf{M}|\le r-1$, and therefore
\begin{align}
&\varphi_{\mathbf{M}}\left(
\mathcal N\left(
\widetilde{WB}_{N,n,r}(\mathbf{w}_{\mathbf{M}}|\mathbf{w}|\mathbf{I})
\right)
\right)
\subset[-s^2,(N-s)(2N-s)-1].
\label{eq:typeB-strict-smallness-sufficient-condition}
\end{align}

\label{thm:BC-equal-cardinality-orthogonality}
For $X\in\{B,C\}$ and any $r$-element subsets
$\mathbf J,\mathbf K\subset[N]$,
\begin{align}
&\sum_{\substack{\mathbf M\subset[N]\\|\mathbf M|=r}}
\frac{
q^{p(\mathbf K)}P_{\mathbf M}(\mathbf w)
}{
R_{\mathbf M}(\mathbf w)
Q_{\mathbf M}(\mathbf w,q)
D^X_r(\mathbf M;\mathbf w,q)
D^X_r(\mathbf M;\mathbf w^{-1},q^{-1})
}
\notag\\
&\qquad\times
\widetilde{WX}_{N,n,r}
\bigl((\mathbf w^{\rho})_{\rho(\mathbf M)}
\,|\mathbf w^{\rho}\,|\rho(\mathbf J)\bigr)
\left.
\widetilde{WX}_{N,n,r}
\bigl((\mathbf w^{-1})_{\mathbf M}
\,|\mathbf w^{-1}\,|\mathbf K\bigr)
\right|_{q\mapsto q^{-1}}
=\delta_{\mathbf J,\mathbf K}.
\label{eq:BC-equal-cardinality-orthogonality}
\end{align}

This is a direct rewriting of the type $A$ orthogonality relation
\eqref{eq:RTV-Gr-orthogonality}.  Setting $\mathbf z=\mathbf w$ and $h=q$
in that relation gives
\begin{align*}
\delta_{\mathbf J,\mathbf K}
={}&
\sum_{\substack{\mathbf M\subset[N]\\ |\mathbf M|=r}}
q^{p(\mathbf K)}
\frac{
P_{\mathbf M}(\mathbf w)
}{
R_{\mathbf M}(\mathbf w)Q_{\mathbf M}(\mathbf w,q)
}
\\
&\qquad\times
\widetilde W^{\mathrm{RTV}}_{\mathrm{id},\mathcal J}
(w_{m_1},\ldots,w_{m_r},\mathbf w,q)
\,
\widetilde W^{\mathrm{RTV}}_{\sigma_0,\mathcal K}
(w_{m_1}^{-1},\ldots,w_{m_r}^{-1},
 \mathbf w^{-1},q^{-1}),
\end{align*}
where
$
\mathcal J=(\mathbf J,\mathbf J^{\mathrm c}), \
\mathcal K=(\mathbf K,\mathbf K^{\mathrm c}).$
By \eqref{eq:PhiX-def} and
\eqref{eq:RTV-id-via-reversal},
\begin{equation}
\widetilde W^{\mathrm{RTV}}_{\mathrm{id},\mathcal J}
(w_{m_1},\ldots,w_{m_r},\mathbf w,q)
=
\Phi_{\rho(\mathbf M),\rho(\mathbf J)}
(\mathbf w^{\rho},q).
\label{eq:PhiX-op-is-id}
\end{equation}
Using \eqref{eq:PhiX-is-RTV} with
$(\mathbf M,\mathbf I,\mathbf w)$ replaced by
$(\rho(\mathbf M),\rho(\mathbf J),\mathbf w^{\rho})$, and then
\eqref{eq:local-D-reversal}, we obtain
\[
\widetilde W^{\mathrm{RTV}}_{\mathrm{id},\mathcal J}
(w_{m_1},\ldots,w_{m_r},\mathbf w,q)
=
\frac{
\widetilde{WX}_{N,n,r}
\bigl(
(\mathbf w^{\rho})_{\rho(\mathbf M)}
\,|\mathbf w^{\rho}\,|\rho(\mathbf J)
\bigr)
}{
D^X_r(\mathbf M;\mathbf w,q)
}.
\]
Similarly, \eqref{eq:PhiX-def} and \eqref{eq:PhiX-is-RTV}, after the
substitution $(\mathbf w,q)\mapsto(\mathbf w^{-1},q^{-1})$, give
\[
\widetilde W^{\mathrm{RTV}}_{\sigma_0,\mathcal K}
(w_{m_1}^{-1},\ldots,w_{m_r}^{-1},
 \mathbf w^{-1},q^{-1})
=
\frac{
\left.
\widetilde{WX}_{N,n,r}
\bigl(
(\mathbf w^{-1})_{\mathbf M}
\,|\mathbf w^{-1}\,|\mathbf K
\bigr)
\right|_{q\mapsto q^{-1}}
}{
D^X_r(\mathbf M;\mathbf w^{-1},q^{-1})
}.
\]
Substituting these two identities into
\eqref{eq:RTV-Gr-orthogonality} gives
\eqref{eq:BC-equal-cardinality-orthogonality}.

\label{cor:Phi-inverse}
The matrix $\Phi^{(r)}(\mathbf w,q)$ is invertible.  Its inverse is given by
\begin{align}
\bigl(\Phi^{(r)}(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf K}
={}&
q^{-p(\mathbf I)}
\frac{
P_{\mathbf K}(\mathbf w^{-1})
}{
R_{\mathbf K}(\mathbf w^{-1})
Q_{\mathbf K}(\mathbf w^{-1},q^{-1})
}
\Phi_{\rho(\mathbf K),\rho(\mathbf I)}
\bigl((\mathbf w^{-1})^{\rho},q^{-1}\bigr).
\label{eq:Phi-inverse}
\end{align}

\label{thm:BC-all-cardinality-biorthogonality}
For $X\in\{B,C\}$ and arbitrary subsets $\mathbf M,\mathbf L\subset[N]$,
\begin{equation}
\sum_{\mathbf I\subset[N]}
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf L)|}
\mathsf A^X_{\mathbf M,\mathbf I}(\mathbf w,q)
\mathsf A^X_{\mathbf L^{\mathrm c},\mathbf I^{\mathrm c}}
(\mathbf w,q^{-1})
=\delta_{\mathbf M,\mathbf L}.
\label{eq:BC-all-cardinality-biorthogonality-matrix}
\end{equation}
Equivalently,
\begin{align}
&\sum_{\mathbf I\subset[N]}
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf L)|}
\frac{
\widetilde{WX}_{N,N,|\mathbf I|}
(\mathbf w_{\mathbf M}\,|\mathbf w\,|\mathbf I)
}{\Delta^X_{\mathbf M}(\mathbf w,q)}
\frac{
\left.
\widetilde{WX}_{N,N,N-|\mathbf I|}
(\mathbf w_{\mathbf L^{\mathrm c}}\,|\mathbf w\,|\mathbf I^{\mathrm c})
\right|_{q\mapsto q^{-1}}
}{
\Delta^X_{\mathbf L^{\mathrm c}}(\mathbf w,q^{-1})
}
=\delta_{\mathbf M,\mathbf L}.
\label{eq:BC-all-cardinality-biorthogonality}
\end{align}

\label{lem:allcard-Phihat-inverse}
For arbitrary subsets $\mathbf I,\mathbf K\subset[N]$,
\begin{equation}
\bigl(\widehat\Phi(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf K}
=
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf K)|}
\widehat\Phi_{\mathbf K^{\mathrm c},\mathbf I^{\mathrm c}}
(\mathbf w,q^{-1}).
\label{eq:allcard-Phihat-inverse-components}
\end{equation}
Both sides are zero unless $|\mathbf I|=|\mathbf K|$.

\label{lem:allcard-Bhat-product}
Let $\mathbf K\subset\mathbf M$ and put
$\Omega=\mathbf M\setminus\mathbf K$.  Then
\begin{align}
\widehat{\mathrm{Br}}{}^C_{\mathbf M,\mathbf K}(\mathbf w,q)
={}&
(1-q)^{|\Omega|}
\prod_{t\in\Omega}\frac{1}{1-w_t^{-2}}
\prod_{\substack{a<b\\a,b\in\Omega}}
\frac{1-qw_a^{-1}w_b^{-1}}{1-w_a^{-1}w_b^{-1}}
\notag\\
&\times
\prod_{\substack{k\in\mathbf K,\ t\in\Omega\\k<t}}
\frac{1-qw_k^{-1}w_t}{1-w_k^{-1}w_t}
\prod_{\substack{t\in\Omega,\ j\in\mathbf M^{\mathrm c}\\j<t}}
\frac{1-qw_t^{-1}w_j}{1-w_t^{-1}w_j},
\label{eq:allcard-Bhat-product-C}
\end{align}
and
\begin{align}
\widehat{\mathrm{Br}}{}^B_{\mathbf M,\mathbf K}(\mathbf w,q)
={}&
(1-q)^{|\Omega|}
\prod_{t\in\Omega}\frac{1}{1-w_t^{-1}}
\prod_{\substack{a<b\\a,b\in\Omega}}
\frac{1-qw_a^{-1}w_b^{-1}}{1-w_a^{-1}w_b^{-1}}
\notag\\
&\times
\prod_{\substack{k\in\mathbf K,\ t\in\Omega\\k<t}}
\frac{1-qw_k^{-1}w_t}{1-w_k^{-1}w_t}
\prod_{\substack{t\in\Omega,\ j\in\mathbf M^{\mathrm c}\\j<t}}
\frac{1-qw_t^{-1}w_j}{1-w_t^{-1}w_j}.
\label{eq:allcard-Bhat-product-B}
\end{align}

\label{lem:allcard-universal-cancellation}
For $m\ge1$ and generic variables $x_1,\ldots,x_m$,
\begin{equation}
\sum_{\epsilon\in\{0,1\}^m}
(-1)^{m-|\epsilon|}
\prod_{1\le i<j\le m}
H_{\epsilon_i,\epsilon_j}(x_i,x_j)=0,
\label{eq:allcard-universal-cancellation}
\end{equation}
where $|\epsilon|=\epsilon_1+\cdots+\epsilon_m$.

\label{prop:allcard-Bhat-inverse}
For $X\in\{B,C\}$,
\begin{equation}
\bigl(\widehat{\mathrm{Br}}{}^X(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf M}
=
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf M)|}
\widehat{\mathrm{Br}}{}^X_{\mathbf M^{\mathrm c},\mathbf I^{\mathrm c}}
(\mathbf w,q^{-1}).
\label{eq:allcard-Bhat-inverse}
\end{equation}

From \eqref{eq:allcard-P-factorization},
\[
\mathsf A^X(\mathbf w,q)^{-1}
=
\widehat\Phi(\mathbf w,q)^{-1}
\widehat{\mathrm{Br}}{}^X(\mathbf w,q)^{-1}.
\]
The first equality below is the $(\mathbf I,\mathbf L)$ entry of the
matrix product. The second follows from Lemma~\ref{lem:allcard-Phihat-inverse}
and Proposition~\ref{prop:allcard-Bhat-inverse}; the last equality uses
\eqref{eq:allcard-P-factorization}:
\begin{align}
\bigl(\mathsf A^X(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf L}
&=
\sum_{\mathbf K\subset[N]}
\bigl(\widehat\Phi(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf K}
\bigl(\widehat{\mathrm{Br}}{}^X(\mathbf w,q)^{-1}\bigr)_{\mathbf K,\mathbf L}
\notag\\
&=
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf L)|}
\sum_{\mathbf K\subset[N]}
\widehat{\mathrm{Br}}{}^X_{\mathbf L^{\mathrm c},\mathbf K^{\mathrm c}}
(\mathbf w,q^{-1})
\widehat\Phi_{\mathbf K^{\mathrm c},\mathbf I^{\mathrm c}}
(\mathbf w,q^{-1})
\notag\\
&=
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf L)|}
\left(\widehat{\mathrm{Br}}{}^X(\mathbf w,q^{-1})
\widehat\Phi(\mathbf w,q^{-1})\right)_{\mathbf L^{\mathrm c},\mathbf I^{\mathrm c}}
\notag\\
&=
q^{|\lambda(\mathbf I)|-|\lambda(\mathbf L)|}
\mathsf A^X_{\mathbf L^{\mathrm c},\mathbf I^{\mathrm c}}
(\mathbf w,q^{-1}).
\end{align}
The identity
$\mathsf A^X(\mathbf w,q)\mathsf A^X(\mathbf w,q)^{-1}=\mathrm{Id}$ is exactly
\eqref{eq:BC-all-cardinality-biorthogonality-matrix}; expanding the definition
\eqref{eq:allcard-A-def} gives
\eqref{eq:BC-all-cardinality-biorthogonality}.

Take $N=2$ and $X=C$.  By \eqref{eq:allcard-Delta-factor},
Theorem~\ref{RTVtheorem} $\mathrm{(ii)}$, and
\eqref{general-diagonal-factor},
\begin{align}
\Delta^C_{\{1\}}(\mathbf w,q)
&=(1-w_1^{-2})(1-qw_2^2)
\left(1-q\frac{w_2}{w_1}\right),
 \notag\\
\Delta^C_{\{2\}}(\mathbf w,q)
&=(1-w_2^{-2})(1-qw_1^2)
\left(1-\frac{w_1}{w_2}\right),
 \notag\\
\Delta^C_{\{2\}}(\mathbf w,q^{-1})
&=(1-w_2^{-2})(1-q^{-1}w_1^2)
\left(1-\frac{w_1}{w_2}\right).
 \notag
\end{align}
In terms of the normalized type $C$ functions, these are
\begin{align*}
\Delta^C_{\{1\}}(\mathbf w,q)
&=\widetilde{WC}_{2,2,1}
\bigl(w_1,1\,|\mathbf w\,|\{1\}\bigr),\\
\Delta^C_{\{2\}}(\mathbf w,q)
&=\widetilde{WC}_{2,2,1}
\bigl(w_2,1\,|\mathbf w\,|\{2\}\bigr),\\
\Delta^C_{\{2\}}(\mathbf w,q^{-1})
&=\left.\widetilde{WC}_{2,2,1}
\bigl(w_2,1\,|\mathbf w\,|\{2\}\bigr)
\right|_{q\mapsto q^{-1}}.
\end{align*}
The remaining values needed below are
\begin{align}
\widetilde{WC}_{2,2,1}
\bigl(w_2,1\,|\mathbf w\,|\{1\}\bigr)
&=(1-w_2^{-2})(1-qw_1^2)(1-q),
 \notag\\
\left.\widetilde{WC}_{2,2,1}
\bigl(w_2,1\,|\mathbf w\,|\{1\}\bigr)
\right|_{q\mapsto q^{-1}}
&=(1-w_2^{-2})(1-q^{-1}w_1^2)(1-q^{-1}).
 \notag
\end{align}
The support and lower-cardinality vanishing relations give
\begin{align}
\widetilde{WC}_{2,2,1}
\bigl(w_1,1\,|\mathbf w\,|\{2\}\bigr)&=0,
\label{eq:allcard-N2-WC12zero}\\
\widetilde{WC}_{2,2,2}
\bigl(w_i,1\,|\mathbf w\,|\{1,2\}\bigr)&=0
\qquad(i=1,2).
\label{eq:allcard-N2-WC2zero}
\end{align}

\label{cor:BC-branching-formula-inversion}
Let $X\in\{B,C\}$ and $0\le r\le\min(n,N)$.
Let $\mathbf K\subset[N]$ be an $r$-element subset, and let
$\mathbf M\subset[N]$ have cardinality
$0\le s=|\mathbf M|\le\min(n,N)$.
Then
\begin{align}
&\sum_{\substack{\mathbf I\subset[N]\\|\mathbf I|=r}}
\widetilde{WX}_{N,n,r}
(\mathbf w_{\mathbf M}\,|\mathbf w\,|\mathbf I)
\bigl(\Phi^{(r)}(\mathbf w,q)^{-1}\bigr)_{\mathbf I,\mathbf K}
=
\begin{cases}
\operatorname{Br}^X_{\mathbf M,\mathbf K}(\mathbf w,q),
&s\ge r\text{ and }\mathbf K\subset\mathbf M,\\[2mm]
0,&\text{otherwise}.
\end{cases}
\label{eq:allcard-branching-inversion}
\end{align}

\cite[Theorem 6.6, Grassmannian specialization]{RTV}
\label{thm:RTV-Gr-orthogonality}
For any two $r$-element subsets
$\mathbf J,\mathbf K\subset\{1,\ldots,N\}$, with
$\mathcal J=(\mathbf J,\mathbf J^{\mathrm c})$ and
$\mathcal K=(\mathbf K,\mathbf K^{\mathrm c})$, one has
\begin{align}
&\sum_{\substack{\mathbf M\subset\{1,\ldots,N\}\\|\mathbf M|=r}}
\frac{
h^{p(\mathbf K)}P_{\mathbf M}(\mathbf z)
}{
R_{\mathbf M}(\mathbf z)
Q_{\mathbf M}(\mathbf z,h)
}
\widetilde W_{\mathrm{id},\mathcal J}^{\mathrm{RTV}}
(\mathbf z_{\mathbf M},\mathbf z,h)
\widetilde W_{\sigma_0,\mathcal K}^{\mathrm{RTV}}
(\mathbf z_{\mathbf M}^{-1},\mathbf z^{-1},h^{-1})
=\delta_{\mathbf J,\mathbf K}.
\label{eq:RTV-Gr-orthogonality}
\end{align}
